{
        if (Z_TYPE_P(zvalue) == IS_ARRAY) {
                ZVAL_ARR(zvalue, zend_array_dup(Z_ARR_P(zvalue)));
        } else if (Z_REFCOUNTED_P(zvalue)) {
                Z_ADDREF_P(zvalue);
        }
}

